mapper.select:
SELECT
p.SOU_NO,
p.EXT_PROJECT_NO,
p.SOU_NAME,
p.EXT_SOU_PROCESS,
p.EXT_CATEGORY_NAME,
p.EXT_ORG_BU_CODE,
p.EXT_ORG_BU_NAME,
p.EXT_ORG_OU_CODE,
p.EXT_ORG_OU_NAME,
p.EXT_SCALE_QUANTITY,
p.EXT_BUDGET,
p.PROJECT_STATUS,
p.CREATION_DATE BID_CREATION_DATE,
s.*
from scc_npm_sou_schedule s
join scc_sou_project p on p.PROJECT_ID = s.PROJECT_ID and p.SOU_TYPE='bid' and p.CREATE_APPROVAL_STATUS='APPROVED'


        and s.REQUIREMENT_PLAN_TYPE = #{requirementPlanType}


        and p.EXT_ORG_BU_NAME like CONCAT('%',#{extOrgBuName},'%')


        and p.EXT_ORG_OU_NAME like CONCAT('%',#{extOrgOuName},'%')


        and s.COMPANY_SHORT_CODE like CONCAT('%',#{companyShortCode},'%')


        and s.YEAR like CONCAT('%',#{year},'%')


        and s.MONTH like CONCAT('%',#{month},'%')


        and p.EXT_ORG_BU_CODE like CONCAT('%',#{extOrgBuCode},'%')


        and p.EXT_PROJECT_NO like CONCAT('%',#{extProjectNo},'%')


        and p.SOU_NAME like CONCAT('%',#{souName},'%')


        and p.EXT_SOU_PROCESS = #{extSouProcess}


        and p.EXT_CATEGORY_ID = #{extCategoryId}


        and p.EXT_CATEGORY_NAME like CONCAT('%',#{extCategoryName},'%')


        and s.SOU_PRINCIPAL like CONCAT('%',#{souPrincipal},'%')


        and s.VENDOR_PRINCIPAL like CONCAT('%',#{vendorPrincipal},'%')


        and p.EXT_BUDGET >= #{totalBudgetFrom}


        and p.EXT_BUDGET <= #{totalBudgetTo}


        and s.HONOUR_SCORE >= #{honourScoreFrom}


        and s.HONOUR_SCORE <= #{honourScoreTo}


        and s.HONOUR_RESULT = #{honourResult}


        and p.PROJECT_STATUS = #{projectStatus}


        and s.ADD_BID_NUMBER >= #{addBidNumber}


        and s.ADD_BID_AS_SUBMIT_NUMBER >= #{addBidAsSubmitNumber}


        and s.NEW_VENDOR_BID_NUMBER >= #{newVendorBidNumber}


        and s.NEW_UNITE_VENDOR_BID_NUMBER >= #{newUniteVendorBidNumber}


        and s.TOTAL_BID_NUMBER <= #{totalBidNumber}


        and s.TOTAL_BID_AS_SUBMIT_NUMBER <= #{totalBidAsSubmitNumber}


        and s.VENDOR_POSTPONE_CYCLE >= #{vendorPostponeCycle}


        and s.ACCEPTANCE_POSTPONE_CYCLE >= #{acceptancePostponeCycle}


        and s.SUM_REPORT_POSTPONE_CYCLE >= #{sumReportPostponeCycle}


        and s.DATA_SUBMIT_POSTPONE_CYCLE >= #{dataSubmitPostponeCycle}


        and s.EVALUATION_POSTPONE_CYCLE >= #{evaluationPostponeCycleFrom}


        and s.EVALUATION_POSTPONE_CYCLE <= #{evaluationPostponeCycleTo}


        and s.PICKETAGE_POSTPONE_CYCLE >= #{picketagePostponeCycleFrom}


        and s.PICKETAGE_POSTPONE_CYCLE <= #{picketagePostponeCycleTo}


        and s.ANSWER_ISSUED_COUNT >= #{answerIssuedCount}



ORDER BY p.PROJECT_ID DESC
